package com.companages.service;
import com.companages.dto.*; import com.companages.entity.*; import com.companages.repository.ActivityLogRepository; import jakarta.persistence.criteria.Predicate; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.ArrayList;
@Service public class ActivityService { private final ActivityLogRepository logs; private final CurrentUserService current; private final OrganizationAccessService access; public ActivityService(ActivityLogRepository l,CurrentUserService c,OrganizationAccessService a){logs=l;current=c;access=a;} public void record(Organization org,ActivityAction action,String targetType,Object targetId,String metadata){ActivityLog log=new ActivityLog();log.setOrganization(org);log.setActor(current.get());log.setAction(action);log.setTargetType(targetType);log.setTargetId(targetId==null?null:String.valueOf(targetId));log.setMetadata(metadata);logs.save(log);} @Transactional(readOnly=true) public PageResponse<ActivityDtos.Response> list(Long oid,ActivityAction action,Long actorId,Instant from,Instant to,Pageable pageable){access.requireMember(oid);Specification<ActivityLog> spec=(root,query,cb)->{var predicates=new ArrayList<Predicate>();predicates.add(cb.equal(root.get("organization").get("id"),oid));if(action!=null)predicates.add(cb.equal(root.get("action"),action));if(actorId!=null)predicates.add(cb.equal(root.get("actor").get("id"),actorId));if(from!=null)predicates.add(cb.greaterThanOrEqualTo(root.get("createdAt"),from));if(to!=null)predicates.add(cb.lessThanOrEqualTo(root.get("createdAt"),to));return cb.and(predicates.toArray(Predicate[]::new));};return PageResponse.from(logs.findAll(spec,pageable),this::map);} private ActivityDtos.Response map(ActivityLog a){return new ActivityDtos.Response(a.getId(),a.getAction(),a.getActor()==null?null:a.getActor().getId(),a.getActor()==null?"System":a.getActor().getName(),a.getTargetType(),a.getTargetId(),a.getMetadata(),a.getCreatedAt());} }
